"use strict";(self.webpackChunkmonogame_extended_website=self.webpackChunkmonogame_extended_website||[]).push([[4402],{7803:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>m,frontMatter:()=>a,metadata:()=>r,toc:()=>d});var o=n(4848),i=n(8453);const a={slug:"update-2025-01",title:"January 2025 Update",authors:"aris",tags:["updates","tilemaps","monogame"],enableComments:!0},s=void 0,r={permalink:"/blog/update-2025-01",editUrl:"https://github.com/monogame-extended/monogame-extended.github.io/tree/develop/blog/2026-01-24/update-2025-01/update-2025-01.md",source:"@site/blog/2026-01-24/update-2025-01/update-2025-01.md",title:"January 2025 Update",description:"Hi everyone,",date:"2026-01-24T00:00:00.000Z",tags:[{inline:!1,label:"Updates",permalink:"/blog/tags/updates",description:"Updates to the MonoGame.Extended library."},{inline:!0,label:"tilemaps",permalink:"/blog/tags/tilemaps"},{inline:!0,label:"monogame",permalink:"/blog/tags/monogame"}],readingTime:3.985,hasTruncateMarker:!1,authors:[{name:"Christopher Whitley (AristurtleDev)",title:"MonoGame.Extended Maintainer",url:"https://github.com/aristurtledev",imageURL:"https://github.com/aristurtledev.png",key:"aris"}],frontMatter:{slug:"update-2025-01",title:"January 2025 Update",authors:"aris",tags:["updates","tilemaps","monogame"],enableComments:!0},unlisted:!1,nextItem:{title:"Version 5.3.1 Release - BMFont Improvements",permalink:"/blog/version-5-3-1"}},l={authorsImageUrls:[void 0]},d=[{value:"Current Focus: Tilemap System Overhaul",id:"current-focus-tilemap-system-overhaul",level:2},{value:"A Decision to Benefit the Broader Ecosystem",id:"a-decision-to-benefit-the-broader-ecosystem",level:2},{value:"Tilemap System Progress",id:"tilemap-system-progress",level:2},{value:"Address ContentBuilder Compatibility Concerns",id:"address-contentbuilder-compatibility-concerns",level:2},{value:"Looking Ahead",id:"looking-ahead",level:2}];function h(e){const t={a:"a",em:"em",h2:"h2",p:"p",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.p,{children:"Hi everyone,"}),"\n",(0,o.jsx)(t.p,{children:"It's been a couple of months since my last update, and I wanted to take some time to catch you up on what's been happening with MonoGame.Extended and where things are headed."}),"\n",(0,o.jsx)(t.h2,{id:"current-focus-tilemap-system-overhaul",children:"Current Focus: Tilemap System Overhaul"}),"\n",(0,o.jsx)(t.p,{children:"Following the initial release of Ember and the 5.3 release that addressed various bug fixes and improvements, my focus has shifted to the tilemap system overhaul that has been planned for some time.  One of the first challenges to tackle in this is how tile collisions will be handled."}),"\n",(0,o.jsxs)(t.p,{children:["Previously ",(0,o.jsx)(t.a,{href:"https://github.com/lithiumtoast",children:"@lithiumtoast"})," has started work on refactoring the collision system in MonoGame.Extended based on information from the ",(0,o.jsx)(t.em,{children:"Real-Time Collision Detection"})," book by Christer Ericson.  I decided to pick up from where that work left off and continue moving forward with it."]}),"\n",(0,o.jsx)(t.h2,{id:"a-decision-to-benefit-the-broader-ecosystem",children:"A Decision to Benefit the Broader Ecosystem"}),"\n",(0,o.jsxs)(t.p,{children:["After spending some time working on the collision implementation, I came to an important realization: this might be an area where the MonoGame ecosystem as a whole would benefit from having these implementations in MonoGame itself, rather than exclusively in MonoGame.Extended.  I reached out to the MonoGame Foundation about the idea and opened a ",(0,o.jsx)(t.a,{href:"https://github.com/MonoGame/MonoGame/issues/9133",children:"discussion issue"})," to gauge interest. Responses from all were positive and everyone was on board with moving forward with this direction."]}),"\n",(0,o.jsxs)(t.p,{children:["I have submitted a ",(0,o.jsx)(t.a,{href:"https://github.com/MonoGame/MonoGame/pull/9160",children:"pull request to implement a 2D bounding volumes and primitives suite into MonoGame"}),".  This initial PR took some time as I worked through the reference material in Ericson's book and designed the implementation.  The PR came out of draft status las week.  Since the MonoGame Foundation is currently focused on the 3.8.5 release, this PR will most likely not be merged until MonoGame 3.8.6.  In the meantime, I will offer it as a compatibility package within MonGame.Extended, with a release coming soon on that."]}),"\n",(0,o.jsx)(t.h2,{id:"tilemap-system-progress",children:"Tilemap System Progress"}),"\n",(0,o.jsx)(t.p,{children:"With the collision foundation now implemented, I have begun work on the actual tilemap system according to the original plan.  This is a substantial undertaking,a nd I am estimating it will take around two months for the initial release, depending on various factors."}),"\n",(0,o.jsx)(t.p,{children:"During this time, I also have other obligations that require attention within the broader MonoGame ecosystem.  This includes keeping the 2D tutorial updated and addressing feedback, working on website improvements and integrations for MonoGame, and addressing issues that come up with future tutorials being written for the MonoGame Foundation that make use of MonoGame.Extended."}),"\n",(0,o.jsx)(t.h2,{id:"address-contentbuilder-compatibility-concerns",children:"Address ContentBuilder Compatibility Concerns"}),"\n",(0,o.jsx)(t.p,{children:"I also want to take a moment to address a concern that has come up regarding the current state of using the MonoGame.Extended.Content.Pipeline extension with the new MonoGame 3.8.5 ContentBuilder project."}),"\n",(0,o.jsxs)(t.p,{children:["First, if you haven't seen the new ContentBuilder project coming in MonoGame 3.8.5, I highly recommend checking it out and trying it.  You can read more about it in the ",(0,o.jsx)(t.a,{href:"https://docs.monogame.net/articles/getting_started/content_pipeline/content_builder_project.html?tabs=vscode",children:"Working with new Content Builder Projects"})," on the MonoGame website.  This new ContentBuilder project will create a simpler and more intuitive way to manage assets for your MonoGame projects compared to using the current MGCB Editor.  However, since this is a new project type, there are some breaking changes that are not playing well with MonoGame.Extended.Content.Pipeline at the moment.  Specifically, importing Tiled (.tmx) tilemaps is having issues due to how external references are built when importing and processing tilemap data."]}),"\n",(0,o.jsxs)(t.p,{children:["I have addressed some of these concerns in a ",(0,o.jsx)(t.a,{href:"https://discord.com/channels/355231098122272778/1462551807849926950",children:"thread in the MonoGame Discord"}),", but i find myself at a crossroads here.  The tilemap system in MonoGame.Extended is getting a complete overhaul, which will include refactoring how content assets are imported through the content pipeline.  So this issue will naturally be address as part of that work."]}),"\n",(0,o.jsx)(t.p,{children:"The alternative would be to spend time patching the current Tiled implementation to work with ContentBuilder, which will be replaced soon anyway with the new system.  After weighing the options, I believe my time is better spent focusing on the tilemap overhaul rather than applying temporary patches to a system that is being replaced."}),"\n",(0,o.jsx)(t.p,{children:"If this is a pressing issue for your project, I encourage the community to work on a solution.  If the issue remains unresolved by the time MonoGame 3.8.5 comes out of preview, suers should still be able to use the MGCB Editor to import Tiled (.tmx) files specifically, as the MGCB Editor itself is not going away."}),"\n",(0,o.jsx)(t.h2,{id:"looking-ahead",children:"Looking Ahead"}),"\n",(0,o.jsx)(t.p,{children:"The next couple of months will be focused on completing the tilemap system overhaul.  This area is one of the most requested and used features in MonoGame.Extended, and I am commit to delivering a solid implementation."}),"\n",(0,o.jsxs)(t.p,{children:["As always, if you have any questions or concerns, please let me know in the comments below or reach out on the ",(0,o.jsx)(t.a,{href:"https://discord.gg/FvZ8Z7EzPJ",children:"MonoGame.Extended Discord"}),".  Thank you all for your patience and continue support of this project."]}),"\n",(0,o.jsxs)(t.p,{children:["- \u2764\ufe0f Chris Whitley (",(0,o.jsx)(t.a,{href:"https://github.com/aristurtledev",children:"AristurtleDev"}),")"]})]})}function m(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h(e)}},8453:(e,t,n)=>{n.d(t,{R:()=>s,x:()=>r});var o=n(6540);const i={},a=o.createContext(i);function s(e){const t=o.useContext(a);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(a.Provider,{value:t},e.children)}}}]);